import re
from datetime import datetime

_DIGITS = "0123456789"
_DISPLAY_NAME_RE = re.compile(r"<([^<>]*)>")
_PHONE_EXT_RE = re.compile(r"ext|x|#", re.IGNORECASE)
_ZIP4_RE = re.compile(r"([0-9]{4,5})-[0-9]{4}")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")


def _all_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _normalize_email(raw):
    s = (raw or "").strip()
    m = _DISPLAY_NAME_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _is_valid_email(e):
    if e.count("@") != 1:
        return False
    local, domain = e.split("@")
    if not local:
        return False
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return False
    return True


def _normalize_phone(raw):
    s = raw or ""
    m = _PHONE_EXT_RE.search(s)
    if m:
        s = s[:m.start()]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(p):
    return len(p) == 10 and p[0] not in "01"


def _normalize_zip(raw):
    s = (raw or "").strip()
    m = _ZIP4_RE.fullmatch(s)
    if m:
        s = m.group(1)
    if len(s) == 4 and _all_digits(s):
        s = "0" + s
    return s if len(s) == 5 and _all_digits(s) else ""


def _normalize_name(raw):
    s = (raw or "").strip()
    if s and (s.isupper() or s.islower()):
        s = s.title()
    return s


def _parse_updated(raw):
    s = (raw or "").strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None


def _normalize_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw or "") if t.strip()}


def _is_opted_out(raw):
    return (raw or "").strip().lower() in ("y", "yes", "true", "1")


def _ts(r):
    return r["updated"] if r["updated"] is not None else datetime.min


def _pick(group, field):
    # Only rows whose normalized value for this field is non-empty qualify.
    # Email and phone are stored as "" when invalid, so this also enforces validity.
    cands = [r for r in group if r[field]]
    cands.sort(key=lambda r: r["idx"])                      # earliest input row
    cands.sort(key=_ts, reverse=True)                       # most recent updated
    cands.sort(key=lambda r: 0 if r["source"] == "manual" else 1)  # manual first
    return cands[0][field] if cands else ""


def dedupe_contacts(rows):
    # Step 1: normalize every row; drop rows with neither a valid email nor phone.
    recs = []
    for idx, row in enumerate(rows):
        def g(key):
            return row.get(key) or ""

        email = _normalize_email(g("email"))
        phone = _normalize_phone(g("phone"))
        email_ok = _is_valid_email(email)
        phone_ok = _is_valid_phone(phone)
        if not (email_ok or phone_ok):
            continue
        recs.append({
            "idx": idx,
            "first_name": _normalize_name(g("first_name")),
            "last_name": _normalize_name(g("last_name")),
            "zip": _normalize_zip(g("zip")),
            "email": email if email_ok else "",
            "phone": phone if phone_ok else "",
            "source": g("source").strip().lower(),
            "tags": _normalize_tags(g("tags")),
            "opted_out": _is_opted_out(g("opted_out")),
            "updated": _parse_updated(g("updated")),
        })

    # Step 2: union-find so matching is transitive.
    parent = list(range(len(recs)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    by_email = {}
    by_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in by_email:
                union(by_email[r["email"]], i)
            else:
                by_email[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].casefold())
            if key in by_phone_last:
                union(by_phone_last[key], i)
            else:
                by_phone_last[key] = i

    # Group rows; groups are ordered by their earliest input row.
    groups = {}
    order = []
    for i in range(len(recs)):
        root = find(i)
        if root not in groups:
            groups[root] = []
            order.append(root)
        groups[root].append(recs[i])

    # Step 3: build one output record per person.
    result = []
    for root in order:
        grp = groups[root]

        tags = set()
        for r in grp:
            tags |= r["tags"]

        dates = [r["updated"] for r in grp if r["updated"] is not None]
        latest = max(dates).strftime("%Y-%m-%d") if dates else ""

        result.append({
            "first_name": _pick(grp, "first_name"),
            "last_name": _pick(grp, "last_name"),
            "zip": _pick(grp, "zip"),
            "email": _pick(grp, "email"),
            "phone": _pick(grp, "phone"),
            "source": _pick(grp, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in grp) else "N",
            "updated": latest,
        })

    return result
```

**Notes on the implementation:**

- **Opt-outs are flagged, not removed.** Per rule 7, `opted_out` is set to "Y" for the person, but the function still returns them. Your send list needs to filter on `opted_out == "N"` before the email goes out.
- **ZIP+4 prefixes:** I accept a 4- or 5-digit prefix before the hyphen (for example, `2139-4307` becomes `02139`), since that's the Excel leading-zero case your rule 4 is meant to catch. If you want only 5-digit prefixes, change `{4,5}` to `{5}` in `_ZIP4_RE`.
- **Extension markers:** "ext" is matched before "x" at the same position, so "ext" is removed in full and not left as a stray "e".
- **Matching:** Last names are compared with `casefold()`, which is a stronger form of case-insensitive comparison than `lower()`.
